<template>
  <div :class="cn('flex flex-col gap-1 rounded-lg bg-muted px-3 py-2 xl:px-4 xl:py-4', props.class)">
    <div class="flex items-baseline justify-between gap-2">
      <span>
        <span class="text-xl xl:text-2xl font-semibold">{{ headline }}</span>
        <span v-if="bar.total" class="text-xs xl:text-sm text-foreground/70">
          / {{ numberFormat.format(bar.total) }}</span
        >
        <span class="text-xs xl:text-sm text-foreground/70">{{ ` ${bar.unit}` }}</span>
      </span>
      <div v-if="highlight.length" class="meta-sep flex flex-wrap items-center gap-x-4 gap-y-1 overflow-hidden">
        <span
          v-for="metric in highlight"
          :key="metric.label"
          class="whitespace-nowrap text-xs xl:text-sm text-foreground font-semibold"
          >{{ metric.label }}: {{ numberFormat.format(metric.value) }}</span
        >
      </div>
    </div>
    <Progress
      :model-value="fillPercent"
      :get-value-label="() => bar.unit"
      class="h-1.5 xl:h-2.5 border-0 bg-background"
      :indicator-class="bar.total ? 'bg-foreground' : 'bg-foreground/50'"
    />
    <div v-if="footer.length" class="meta-sep flex flex-wrap items-center gap-x-4 gap-y-1 overflow-hidden">
      <span v-for="metric in footer" :key="metric.label" class="whitespace-nowrap text-xs text-foreground/70 xl:text-sm"
        >{{ metric.label }}: {{ numberFormat.format(metric.value) }}</span
      >
    </div>
  </div>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue';
import { cn } from '~/components/ui/utils';
import type { ProgressBarData, ProgressMetric } from '~/types/projects/list/progress';

const props = withDefaults(
  defineProps<{
    bar: ProgressBarData;
    highlight?: ProgressMetric[];
    footer?: ProgressMetric[];
    class?: HTMLAttributes['class'];
  }>(),
  {
    highlight: () => [],
    footer: () => [],
    class: undefined,
  }
);

const numberFormat = new Intl.NumberFormat('en-US');

const headline = computed(() => (props.bar.approximate ? '~' : '') + numberFormat.format(props.bar.progress));

const fillPercent = computed(() =>
  props.bar.total ? Math.min(100, Math.max(0, (props.bar.progress / props.bar.total) * 100)) : 100
);
</script>

<style scoped lang="scss">
.meta-sep > * {
  position: relative;
}
.meta-sep > * + *::before {
  content: '·';
  position: absolute;
  right: calc(100% + var(--sep-x, 0.5rem));
  top: 50%;
  transform: translate(50%, -50%);
}
</style>
