<template>
  <div
    :class="
      cn('grid items-center gap-x-2 gap-y-1.5 rounded-lg md:rounded-none border md:border-0 p-2 md:p-1', props.class)
    "
    :style="{ gridTemplateColumns: `1fr repeat(${headerKeys.length}, auto)` }"
  >
    <span class="-mb-1" />
    <span v-for="key in headerKeys" :key="key" class="-mb-1 text-right text-xs text-muted-foreground">{{
      labelFromKey(key)
    }}</span>
    <template v-for="row in tableRows" :key="row.label">
      <span class="text-muted-foreground text-sm xl:text-base">{{ row.label }}</span>
      <span v-for="cell in row.cells" :key="cell.key" class="flex items-center justify-end gap-1 font-semibold">
        <span
          v-if="cell.delta"
          class="hidden xs:block pt-0.5 text-xs font-normal"
          :class="{ 'text-destructive': cell.delta < 0, 'text-success-foreground': cell.delta > 0 }"
          >{{ formatKpiDelta(cell.delta) }}</span
        >
        <span>{{ formatKpiValue(cell.value) }}</span>
        <component
          :is="perfIconDelta(cell.delta)"
          class="size-3.5"
          :class="{
            'text-destructive': cell.delta && cell.delta < 0,
            'text-success-foreground': cell.delta && cell.delta > 0,
          }"
        />
      </span>
      <span v-if="row.comparisonValue !== undefined" class="text-right text-xs text-muted-foreground">{{
        formatKpiValue(row.comparisonValue)
      }}</span>
    </template>
  </div>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue';
import { ArrowDownIcon, ArrowUpIcon, MinusIcon } from 'lucide-vue-next';
import { cn } from '~/components/ui/utils';
import type { KpiTableRow } from '~/types/projects/list/kpiTable';

const props = withDefaults(
  defineProps<{
    columnKeys: string[];
    rows: KpiTableRow[];
    comparisonKey?: string;
    labelFromKey?: (key: string) => string;
    class?: HTMLAttributes['class'];
  }>(),
  {
    comparisonKey: undefined,
    labelFromKey: (key: string) => key,
    class: undefined,
  }
);

const headerKeys = computed(() =>
  props.comparisonKey ? [...props.columnKeys, props.comparisonKey] : props.columnKeys
);

const tableRows = computed(() =>
  props.rows.map((row) => {
    const comparisonValue = props.comparisonKey ? row.data[props.comparisonKey] : undefined;
    return {
      label: row.label,
      comparisonValue,
      cells: props.columnKeys.map((key) => ({
        key,
        value: row.data[key],
        delta: comparisonValue ? roundKpiValue(row.data[key] - comparisonValue) : undefined,
      })),
    };
  })
);

function perfIconDelta(delta?: number): Component {
  if (!delta) return MinusIcon;
  if (delta < 0) return ArrowDownIcon;
  if (delta > 0) return ArrowUpIcon;
  return MinusIcon;
}
</script>
