<template>
  <Card>
    <CardHeader class="grid grid-cols-12">
      <div class="flex flex-col gap-1 w-full col-span-12 md:col-span-9">
        <CardTitle class="text-[20px]/[28px] text-wrap">{{ item.name }}</CardTitle>
        <CardDescription class="text-[16px]/[28px]">
          <p class="w-full line-clamp-1">{{ item.short_description }}</p>
        </CardDescription>
      </div>
      <div class="flex gap-2 col-span-12 md:col-span-3 md:justify-end">
        <NewApplicationsBadge
          v-if="isProjectListItemForManagerOrAdmin(item) && item.users.new_applications > 0"
          :new-applications="item.users.new_applications"
        />
        <Badge v-if="item.status" :variant="getProjectStatus(item.status).variant">{{
          getProjectStatus(item.status).label
        }}</Badge>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <div class="gap-6 sm:gap-2 flex flex-wrap sm:grid sm:grid-cols-3 w-fit">
        <IconLabelValue :icon="BriefcaseBusiness" label="Type">
          <span class="capitalize">{{ item.type }}</span>
        </IconLabelValue>
        <IconLabelValue v-if="isProjectListItemForManagerOrAdmin(item)" :icon="Handshake" label="Client">
          <span class="line-clamp-2">{{ item.client_name }}</span>
        </IconLabelValue>
        <IconLabelValue :icon="CalendarDays" label="Start Date">
          <span>{{ formatDateToFormat(item.start_date, 'MM/dd/yyyy') }}</span>
        </IconLabelValue>
        <template v-if="isProjectListItemForManagerOrAdmin(item)">
          <template v-if="item.statistics?.type === 'signature'">
            <IconLabelValue :icon="CircleCheckBig" label="Raw Verification Rate">
              <span v-if="!Number.isNaN(item.statistics.average_verification_rate)" class="text-md">
                {{ convertVerificationRate(item.statistics.average_verification_rate) }}
              </span>
            </IconLabelValue>
            <IconLabelValue
              :icon="TrendingUp"
              label="Daily Average"
              :value="`${goal(item.statistics.signatures_daily_average.toFixed(0), 'Signatures')}`"
            />
          </template>
          <IconLabelValue
            :icon="UsersRound"
            label="Canvassers"
            :value="`${item.users.active} active / ${item.users.total} total`"
          />
        </template>
      </div>
      <div v-if="item.progress?.type === 'signature'" class="flex flex-col gap-2">
        <div class="flex flex-wrap justify-between items-center">
          <span>Progress</span>
          <span class="text-accent-foreground text-nowrap flex items-center gap-1.5">
            <span class="flex items-center gap-0.5">
              <DotIcon :class="cn('h-4 w-4 stroke-[16px]', validationStatisticsColors.validCollected.stroke)" />{{
                Intl.NumberFormat('en-US').format(item.progress.collected)
              }}
            </span>
            <span>/</span>
            <span class="flex items-center gap-0.5"
              ><DotIcon :class="cn('h-4 w-4 stroke-[16px]', validationStatisticsColors.validNotCollected.stroke)" />
              {{ Intl.NumberFormat('en-US').format(item.progress.total) }}
            </span>
            <span>/</span>
            <span>
              {{ Intl.NumberFormat('en-US').format(item.progress.goal) }}
            </span>
          </span>
        </div>
        <ComposedProgress :segments="getProcessedSegments(item.progress)" />
      </div>
      <div>
        <NuxtLink
          :to="{ name: 'projects-id', params: { id: item.id } }"
          class="text-accent2-foreground text-[14px]/[24px]"
        >
          View Details ->
        </NuxtLink>
      </div>
    </CardContent>
  </Card>
</template>

<script lang="ts" setup>
import type { ProjectListItem } from '~/types/projects/list/item';
import type { SignatureProgress } from '~/client';
import { getProjectStatus } from '~/constants/projects';
import { cn } from '~/components/ui/utils';
import {
  Handshake,
  CircleCheckBig,
  TrendingUp,
  CalendarDays,
  UsersRound,
  BriefcaseBusiness,
  DotIcon,
} from 'lucide-vue-next';
import { validationStatisticsColors } from '~/constants/projects/validationStatistics';

interface Props {
  item: ProjectListItem;
}

defineProps<Props>();

function convertVerificationRate(rate: number): string {
  return `${(rate * 100).toFixed(2).replace(/\.?0+$/, '')}%`;
}

function getProcessedSegments(progress: SignatureProgress) {
  const baseSegments = [
    { value: progress.collected, color: validationStatisticsColors.validCollected.bg },
    { value: progress.not_collected, color: validationStatisticsColors.validNotCollected.bg },
  ];
  return normalizeSegments(baseSegments, progress.goal);
}
</script>

<style scoped lang="scss"></style>
