import { getSelectorClientList, type GetSelectorClientListResponse } from '~/client';

export const useSelectorClientsList = defineQuery(() => {
  const { isAdminOrManager } = useUserRole();

  const { data, isLoading, error } = useQuery({
    key: () => ['selector-clients-list'],
    query: (): Promise<GetSelectorClientListResponse> => getSelectorClientList({ composable: '$fetch' }),
    staleTime: 0,
    enabled: () => isAdminOrManager.value,
  });

  return {
    clients: computed(() => data.value?.items ?? []),
    isLoading,
    error,
  };
});
