<template>
  <section class="flex flex-col gap-6">
    <ProjectListHeader :title="title" :is-admin="isAdmin" :params="params" />
    <AppLoader v-if="isLoading" subject="projects list" />
    <AppError v-else-if="error" title="Failed to load projects list" :error="error" />
    <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" />
    <AppEmpty v-else-if="!projects || projects.items.length === 0" subject="projects" />
    <div v-else class="flex flex-col gap-4">
      <template v-for="item in projects.items" :key="item.id">
        <ProjectListItemV2 v-if="item.type === 'canvassing'" :item="item" data-testid="projects-list-item" />
        <ProjectListItem v-else :item="item" data-testid="projects-list-item" />
      </template>
      <AppPagination
        v-if="projects.total > 0"
        :page="params.page"
        :size="params.size"
        :total="projects.total"
        label="projects"
      />
    </div>
  </section>
</template>

<script setup lang="ts">
import type { ProjectListRequest } from '~/types/projects/list/list';
import { projectsGuidedEmpty, PROJECTS_FILTER_DEFAULTS } from '~/constants/guidedEmpty/projects';
import {
  getProjectList,
  type GetProjectListResponse,
  type ProjectListSortBy,
  type ProjectStatus,
  type ProjectType,
  type SortType,
} from '~/client';

definePageMeta({
  backLabel: 'projects',
});

const { isCanvasserOrSubCanvasser, isAdmin, isAdminOrManager, timezone } = useUserRole();

const title = computed(() => (isCanvasserOrSubCanvasser.value ? 'My Projects' : 'Projects'));

const params: ComputedRef<ProjectListRequest> = computed(() => {
  const urlParams = {
    timezone: timezone.value,
    ...parsePagination(useRoute('projects').query),
    sort_type: (useRoute('projects').query.sort_type || 'desc') as SortType,
    sort_by: (useRoute('projects').query.sort_by || 'start_date') as ProjectListSortBy,
    search_query: (useRoute('projects').query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<ProjectStatus>(useRoute('projects').query.statuses) || [],
    types: processArrayQueryParameterFromUrl<ProjectType>(useRoute('projects').query.types),
    from_date: (useRoute('projects').query.from_date as string) || undefined,
    ...(isAdminOrManager.value && {
      clients: processArrayQueryParameterFromUrl<string>(useRoute('projects').query.clients),
    }),
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as ProjectListRequest;
});

const {
  data: projects,
  error,
  isLoading,
} = useQuery({
  key: () => ['project-list', JSON.stringify(params.value)],
  query: (): Promise<GetProjectListResponse> => getProjectList({ composable: '$fetch', query: params.value }),
  staleTime: 0,
});

const isEmpty = computed(() => !projects.value || projects.value.items.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(projectsGuidedEmpty, isEmpty, PROJECTS_FILTER_DEFAULTS);

useHead({
  title: title.value,
});

onBeforeMount(async () => {
  if (!params.value.statuses || params.value.statuses.length === 0) {
    await navigateTo(
      {
        name: 'projects',
        query: {
          ...useRoute('projects').query,
          statuses: ['draft', 'active'],
        },
      },
      { replace: true }
    );
  }
});
</script>

<style scoped lang="scss"></style>
