<template>
  <ProjectKpiTable
    :column-keys="['today', 'yesterday']"
    comparison-key="avg"
    :rows="rows"
    :label-from-key="columnLabel"
    :class="props.class"
  />
</template>

<script lang="ts" setup>
import type { HTMLAttributes } from 'vue';
import type { CanvassingStats, ComparisonCountsFloat } from '~/client';
import type { KpiTableRow } from '~/types/projects/list/kpiTable';

const props = defineProps<{
  stats: CanvassingStats;
  class?: HTMLAttributes['class'];
}>();

const COLUMN_LABELS: Record<string, string> = {
  today: 'Today',
  yesterday: 'Yest',
  avg: 'Avg',
};

function columnLabel(key: string): string {
  return COLUMN_LABELS[key] ?? key;
}

function asPercent({ today, yesterday, avg }: ComparisonCountsFloat): Record<string, number> {
  return { today: today * 100, yesterday: yesterday * 100, avg: avg * 100 };
}

const rows = computed<KpiTableRow[]>(() => [
  { label: 'Convo rate (%)', data: asPercent(props.stats.convo_rate) },
  { label: 'Doors / hr', data: props.stats.doors_per_hour },
  { label: 'Avg hours (h)', data: props.stats.avg_hours },
  { label: 'Canvassers out', data: props.stats.canvassers_out },
]);
</script>
