<template>
  <ProjectProgressPanel :bar="bar" :highlight="highlight" :footer="footer" />
</template>

<script setup lang="ts">
import type { CanvassingProgress } from '~/client';
import type { ProgressBarData, ProgressMetric } from '~/types/projects/list/progress';

const props = defineProps<{
  progress: CanvassingProgress;
}>();

const bar = computed<ProgressBarData>(() => ({
  progress: props.progress.progress,
  total: props.progress.goal,
  unit: 'doors',
  approximate: props.progress.progress > 4000,
}));

const highlight = computed<ProgressMetric[]>(() => [{ label: 'Today', value: props.progress.today }]);

const footer = computed<ProgressMetric[]>(() => [
  { label: 'Yest', value: props.progress.yesterday },
  { label: 'Avg', value: props.progress.day_average },
  ...(props.progress.daily_target ? [{ label: 'Target', value: props.progress.daily_target }] : []),
]);
</script>
