<template>
  <span class="flex items-center gap-1.5">
    <component
      :is="icon"
      class="size-4 xl:size-5 text-sm xl:text-xl"
      :class="{
        'text-success-foreground': tone === 'success',
        'text-warning-foreground': tone === 'warning',
        'text-accent2-foreground': tone === 'info',
      }"
    />
    <span v-if="label">{{ label }}</span>
    <span :class="{ 'font-semibold': bold, 'ml-auto': !!label }"><slot /></span>
  </span>
</template>

<script setup lang="ts">
withDefaults(
  defineProps<{
    icon: Component;
    bold?: boolean;
    label?: string;
    tone?: 'success' | 'warning' | 'info' | 'none';
  }>(),
  {
    label: undefined,
    bold: false,
    tone: 'none',
  }
);
</script>
