export function roundKpiValue(value: number): number {
  return Number(value.toFixed(2));
}

export function formatKpiValue(value: number): string {
  const rounded = roundKpiValue(value);
  if (Number.isInteger(rounded)) return String(rounded);
  const magnitude = Math.abs(rounded);
  if (magnitude > 99) return rounded.toFixed(0);
  return rounded.toFixed(magnitude < 1 ? 2 : 1);
}

export function formatKpiDelta(delta: number): string {
  return `${delta > 0 ? '+' : ''}${formatKpiValue(delta)}`;
}
